using System.Windows;
using System.Windows.Controls;
using System.Windows.Media.Imaging;
using BoNotesInspector.Core;
namespace BoNotesInspector;
public partial class MainWindow
{
    private void SelectItem(object sender,SelectionChangedEventArgs e){if(loading)return;SaveEditor();editing=(DraftGrid.SelectedItem as DraftRow)?.Item;loading=true;EditTextBox.Text=editing?.Text??"";OriginalTextBox.Text=editing?.OriginalOcr??"";TypeBox.SelectedValue=editing==null?"unknown":NoteParser.Parse(editing.Text).Type;TechnicianBox.SelectedItem=technicians.FirstOrDefault(t=>t.Id==editing?.TechnicianId);TextCheck.IsChecked=editing?.TextVerified??false;DateCheck.IsChecked=editing?.DateVerified??false;SnCheck.IsChecked=editing?.SnVerified??false;BoundaryCheck.IsChecked=editing?.BoundaryVerified??false;SourceText.Text=editing==null?"":$"ผู้โพสต์: {editing.Author}\nเวลาโพสต์ที่เห็น: {editing.PostedText}\nอ่านเมื่อ: {editing.CapturedAt.ToOffset(TimeSpan.FromHours(7)):dd/MM/yyyy HH:mm:ss} (ไทย)\nขอบเขต: {(editing.SourceComplete?"เห็นส่วนต้น/ท้าย":"บางส่วน — ต้องตรวจภาพ")} • รุ่น {editing.Revision}";EvidenceBox.ItemsSource=editing?.EvidenceIds;EvidenceBox.SelectedIndex=0;loading=false;DisplayFields();ShowEvidence();}
    private void SaveEditor(){if(loading||editing==null)return;var tech=TechnicianBox.SelectedItem as Technician;ReviewPolicy.ApplyReview(editing,EditTextBox.Text,tech?.Id??editing.TechnicianId,tech?.FullName??editing.TechnicianName,TextCheck.IsChecked==true,DateCheck.IsChecked==true,SnCheck.IsChecked==true,BoundaryCheck.IsChecked==true);}
    private async void SaveReview(object sender,RoutedEventArgs e){try{SaveEditor();if(store!=null)await store.SaveAsync(batch);var id=editing?.Id;RefreshRows();if(id!=null)DraftGrid.SelectedItem=DraftGrid.Items.OfType<DraftRow>().FirstOrDefault(r=>r.Item.Id==id);StatusText.Text="บันทึกผลตรวจแล้ว หากแก้ข้อมูลต้องส่งออก Excel ใหม่ก่อนนำเข้า";}catch(Exception ex){ShowError(ex);}}
    private void EditChanged(object sender,TextChangedEventArgs e){if(!loading){TextCheck.IsChecked=false;DateCheck.IsChecked=false;SnCheck.IsChecked=false;BoundaryCheck.IsChecked=false;DisplayFields();}}
    private void ChangeType(object sender,SelectionChangedEventArgs e){if(loading||editing==null||TypeBox.SelectedValue is not string type||!NoteParser.TypeTags.TryGetValue(type,out var tag))return;var lines=EditTextBox.Text.Replace("\r\n","\n").Split('\n');EditTextBox.Text=tag+"\n"+string.Join("\n",lines.Skip(1));}
    private void TechnicianChanged(object sender,SelectionChangedEventArgs e){if(!loading){TextCheck.IsChecked=false;SnCheck.IsChecked=false;}}
    private void DisplayFields(){if(!IsInitialized)return;var p=NoteParser.Parse(EditTextBox.Text);FieldsGrid.ItemsSource=p.Fields;ParseWarningsText.Text=string.Join("\n",p.Warnings)+(p.Sns.Count>0?"\nSN ทุกตัวต้องเทียบภาพ รวม 0/O และ 1/I":"\nตรวจภาพว่าข้อความ SN ไม่ตกหล่น");}
    private void SelectEvidence(object sender,SelectionChangedEventArgs e){if(!loading)ShowEvidence();}
    private void ShowEvidence(){if(store==null||EvidenceBox.SelectedItem is not string id){EvidenceImage.Source=null;return;}var asset=batch.Evidence.FirstOrDefault(a=>a.Id==id);if(asset!=null)EvidenceImage.Source=LoadImage(Path.Combine(store.DirectoryPath,"images",asset.FileName));}
    private static BitmapImage LoadImage(string path){var b=new BitmapImage();b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.UriSource=new Uri(path);b.EndInit();b.Freeze();return b;}
    private void ZoomIn(object sender,RoutedEventArgs e){EvidenceScale.ScaleX=EvidenceScale.ScaleY=Math.Min(3,EvidenceScale.ScaleX+.2);}
    private void ZoomOut(object sender,RoutedEventArgs e){EvidenceScale.ScaleX=EvidenceScale.ScaleY=Math.Max(.3,EvidenceScale.ScaleX-.2);}
    private async void AssignTechnician(object sender,RoutedEventArgs e){if(BatchTechBox.SelectedItem is not Technician tech){StatusText.Text="เชื่อม BO ad เพื่อโหลดรายชื่อ แล้วเลือกช่างก่อน";return;}SaveEditor();var selected=batch.Items.Where(i=>i.Selected&&!i.Excluded).ToList();if(selected.Count==0)return;if(System.Windows.MessageBox.Show(this,$"กำหนด {tech.FullName} เป็นเจ้าของ {selected.Count} รายการที่เลือกใช่หรือไม่? ต้องตรวจ SN อีกครั้งหลังเปลี่ยนช่าง","ยืนยันช่าง",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;try{foreach(var i in selected)ReviewPolicy.ApplyReview(i,i.Text,tech.Id,tech.FullName,false,false,false,false);editing=null;RefreshRows();if(store!=null)await store.SaveAsync(batch);StatusText.Text="กำหนดช่างแล้ว กรุณาตรวจและส่งออก Excel ใหม่";}catch(Exception ex){ShowError(ex);}}
}
